      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "theorem",
      "type": "∀ {R : Type u_3} [inst : CommRing R] (t : R) (a : Polynomial R),\n  (Polynomial.algEquivAevalXAddC t) a = (Polynomial.aeval (Polynomial.X + Polynomial.C t)) a"
    },
    {
      "name": "Polynomial.algEquivAevalXAddC",
      "module_name": "Mathlib.Algebra.Polynomial.AlgebraMap",
      "kind": "definition",
      "type": "{R : Type u_3} → [inst : CommRing R] → R → Polynomial R ≃ₐ[R] Polynomial R"
    },
    {
      "name": "MvPolynomial.eval₂_cast_comp",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_4} [inst : CommSemiring R] (f : σ → τ) (c : ℤ →+* R) (g : τ → R)\n  (p : MvPolynomial σ ℤ), MvPolynomial.eval₂ c (g ∘ f) p = MvPolynomial.eval₂ c g ((MvPolynomial.rename f) p)"
    },
    {
      "name": "MvPolynomial.aeval_toMvPolynomial",
      "module_name": "Mathlib.Algebra.MvPolynomial.Equiv",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {S : Type u_2} {σ : Type u_3} [inst : CommSemiring R] [inst_1 : CommSemiring S] [inst_2 : Algebra R S]\n  (f : σ → S) (i : σ) (p : Polynomial R),\n  (MvPolynomial.aeval f) ((Polynomial.toMvPolynomial i) p) = (Polynomial.aeval (f i)) p"
    },
    {
      "name": "MvPolynomial.eval_rename",
      "module_name": "Mathlib.Algebra.MvPolynomial.Rename",
      "kind": "theorem",
      "type": "∀ {σ : Type u_1} {τ : Type u_2} {R : Type u_4} [inst : CommSemiring R] (k : σ → τ) (g : τ → R) (p : MvPolynomial σ R),\n  (MvPolynomial.eval g) ((MvPolynomial.rename k) p) = (MvPolynomial.eval (g ∘ k)) p"
    }
  ]
}
